def solve(grid):
    """
    Fill interior zeros with color 3.
    The input grid contains only two colors: 0 (background) and a non‑zero color that
    forms a closed shape. A zero cell is considered interior if there is a shape cell
    at least two columns away on both the left and the right (or the cell lies on
    the left/right border). The same rule works for the three examples.
    """
    if not grid:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # discover the shape colour (the only non‑zero colour)
    shape_color = None
    for r in grid:
        for v in r:
            if v != 0:
                shape_color = v
                break
        if shape_color is not None:
            break

    # if there is no shape (all zeros) we cannot do anything
    if shape_color is None:
        return grid

    # copy input to output
    out = [row[:] for row in grid]

    for r in range(rows):
        # columns that contain the shape in this row
        shape_cols = [c for c, v in enumerate(grid[r]) if v == shape_color]

        for c in range(cols):
            if grid[r][c] != 0:          # keep the shape unchanged
                continue

            # ----- left side -----
            left_ok = False
            if c == 0:
                left_ok = True            # border counts as valid
            else:
                # nearest shape column to the left
                for lc in reversed(shape_cols):
                    if lc < c:
                        if c - lc >= 2:   # at least one zero between shape and cell
                            left_ok = True
                        break

            # ----- right side -----
            right_ok = False
            if c == cols - 1:
                right_ok = True           # border is valid
            else:
                for rc in shape_cols:
                    if rc > c:
                        if rc - c >= 2:
                            right_ok = True
                        break

            # fill the cell if both sides are satisfied
            if left_ok and right_ok:
                out[r][c] = 3

    return out

